package app.kinnect.live;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;

/** User-visible YouTube website only: no scraping, extraction, hidden/background playback or JS bridge. */
final class YouTubeSongSearch {
 interface Chosen{void select(String title,String url);}
 private final Activity activity;private final Chosen chosen;private Dialog dialog;private WebView web;private TextView status;private String selected="",selectedTitle="";
 YouTubeSongSearch(Activity activity,Chosen chosen){this.activity=activity;this.chosen=chosen;}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 static boolean allowed(String url){try{Uri uri=Uri.parse(url);String h=uri.getHost();return "https".equals(uri.getScheme())&&("m.youtube.com".equals(h)||"www.youtube.com".equals(h)||"youtube.com".equals(h)||"youtu.be".equals(h)||"consent.youtube.com".equals(h));}catch(Exception e){return false;}}
 static String video(String url){try{Uri uri=Uri.parse(url);String host=uri.getHost(),id=null;if(!allowed(url))return null;if("youtu.be".equals(host))id=uri.getLastPathSegment();else if("/watch".equals(uri.getPath()))id=uri.getQueryParameter("v");else if(uri.getPath()!=null&&uri.getPath().startsWith("/shorts/"))id=uri.getLastPathSegment();return id!=null&&id.matches("[A-Za-z0-9_-]{11}")?"https://www.youtube.com/watch?v="+id:null;}catch(Exception e){return null;}}
 private ImageView action(String icon,String label,Runnable click){ImageView v=new ImageView(activity);android.graphics.drawable.Drawable d=WebIcons.load(activity,icon);d.setTint(0xff7652e8);v.setImageDrawable(d);v.setPadding(dp(11),dp(11),dp(11),dp(11));v.setContentDescription(I18n.t(label));v.setOnClickListener(w->click.run());return v;}
 void show(){if(dialog!=null)return;dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout root=new LinearLayout(activity);root.setOrientation(1);root.setBackgroundColor(Color.WHITE);LinearLayout top=new LinearLayout(activity);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(action("x","Đóng",this::close),new LinearLayout.LayoutParams(dp(44),dp(44)));EditText query=new KinnectInput(activity);query.setTextSize(14);query.setTextColor(0xff241b32);query.setHint(I18n.t("Tìm bài YouTube"));query.setSingleLine(true);query.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);top.addView(query,new LinearLayout.LayoutParams(0,dp(48),1));Runnable search=()->{String q=query.getText().toString().trim();if(q.length()<2)return;if(q.length()>120)q=q.substring(0,120);selected="";web.loadUrl("https://m.youtube.com/results?search_query="+Uri.encode(q+" karaoke"));((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);};top.addView(action("search","Tìm kiếm",search),new LinearLayout.LayoutParams(dp(44),dp(44)));root.addView(top);status=new KinnectText(activity);status.setTextSize(11);status.setTextColor(0xff6c5d7c);status.setText(I18n.t("YouTube phát tại đây; nhạc không truyền vào Live."));status.setPadding(dp(12),dp(8),dp(12),dp(8));root.addView(status);
  web=new WebView(activity);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebChromeClient(new WebChromeClient());web.setDownloadListener((u,ua,cd,m,l)->status.setText(I18n.t("Xem/nghe trên YouTube, không tải âm thanh.")));web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return !allowed(request.getUrl().toString());}public boolean shouldOverrideUrlLoading(WebView view,String url){return !allowed(url);}public void onPageFinished(WebView view,String url){String link=video(url);selected=link==null?"":link;selectedTitle=view.getTitle()==null?"YouTube":view.getTitle().replaceFirst(" - YouTube$","");}public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())status.setText(I18n.t("Chưa mở được YouTube. Kiểm tra mạng rồi tìm lại."));}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bottom=new LinearLayout(activity);bottom.setGravity(Gravity.CENTER_VERTICAL);bottom.addView(action("arrow_left","Quay lại",()->{if(web.canGoBack())web.goBack();else close();}),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView select=new KinnectText(activity);select.setText(I18n.t("Chọn bài tham khảo"));select.setTextSize(13);select.setTextColor(0xff7652e8);select.setPadding(dp(12),dp(12),dp(12),dp(12));select.setGravity(Gravity.CENTER);select.setOnClickListener(v->{if(selected.isEmpty()){status.setText(I18n.t("Mở một video trước khi chọn bài."));return;}String title=selectedTitle.length()>120?selectedTitle.substring(0,120):selectedTitle;chosen.select(title,selected);close();});bottom.addView(select,new LinearLayout.LayoutParams(0,-2,1));root.addView(bottom);dialog.setContentView(root);dialog.setOnDismissListener(d->{WebView previous=web;web=null;dialog=null;if(previous!=null){previous.stopLoading();previous.onPause();previous.loadUrl("about:blank");previous.destroy();}});dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(-1,Math.round(activity.getResources().getDisplayMetrics().heightPixels*.86f));w.setGravity(Gravity.BOTTOM);}web.loadUrl("https://m.youtube.com/results?search_query=karaoke");}
 void pause(){if(web!=null)web.onPause();}
 void close(){if(dialog!=null)dialog.dismiss();}
}
